    const kinB = data.buildings.find((x: { key?: string }) => x.key === '547842:357') as { rings: P[][] };
    const kinMeshes = ((inst?.solids ?? []) as { name: string; geometry: { getAttribute: (n: string) => { count: number; getX: (i: number) => number; getY: (i: number) => number; getZ: (i: number) => number } } }[]).filter(m => m.name.startsWith('b06 kin '));
    const kinDetail = ((inst?.detail ?? []) as { name: string; geometry: { getAttribute: (n: string) => { count: number; getX: (i: number) => number; getY: (i: number) => number; getZ: (i: number) => number } } }[]).filter(m => m.name.startsWith('b06 kin '));
