    if (!kinMeshes.length) failures.push('KIN: no b06 kin solids');
    if (outsideK) failures.push(`KIN: ${outsideK} wall vertices outside the official outline ${JSON.stringify(ex)}`);
    if (offLine) failures.push(`KIN: ${offLine} low wall vertices off the official outline / measured tier edges`);
    for (const tr of tierRoofs) if (tr.samples < 10 || !(Math.abs(tr.p50 - tr.target) <= 0.15)) failures.push(`KIN tier ${tr.role} roof P50 ${tr.p50} vs LiDAR tier ${tr.target} (${tr.samples} samples)`);
    if (rows.size < 5) failures.push(`KIN south bar has ${rows.size} window rows (expected 6 storeys)`);
    for (const e of entr) if (e.surroundVertices < 16) failures.push(`KIN entrance missing: ${e.name}`);
